<?php
declare(strict_types=1);
require_once __DIR__.'/mon_reinforcement_fixture.php';
$cases=[];$dirs=[];$started=mon_monotonic();
function ct_ok($v,string $message=''):void{if(!$v)throw new RuntimeException($message?:'assertion failed');}
function ct_case(string $name,callable $fn):void{global $cases;MonExecution::$active=null;MonExecution::$store=null;try{$fn();$cases[]=['case'=>$name,'result'=>'PASS'];}catch(Throwable $e){$cases[]=['case'=>$name,'result'=>'FAIL','error'=>$e->getMessage()];}}
function ct_store():MonStore{global $dirs;$dir=sys_get_temp_dir().'/mon-continuity-'.bin2hex(random_bytes(5));mkdir($dir,0700);$dirs[]=$dir;return new MonStore($dir);}
function ct_cache(MonStore $s,$d,int $age=0):void{$cfg=progress_test_config($s->dir);$copy=clone $d;$copy->_mon_cache=(object)['repository'=>'wskimgit/stock','branch'=>'main','fetched_at'=>mon_iso(time()-$age),'blob_sha'=>MonRun::gitSha(MonRun::json($d)),'data_sha256'=>hash('sha256',MonRun::json($d))];$s->write('remote_cache.json',$copy);}
function ct_fault(callable $f,string $code):void{try{$f();}catch(MonFault $e){ct_ok($e->faultCode===$code,$e->faultCode);return;}throw new RuntimeException('missing fault');}
function ct_has($r,string $kind):bool{foreach($r->pending_jobs as $j)if($j->kind===$kind)return true;return false;}
ct_case('transient remote timeout reuses exact bound cache without refreshing its source timestamp',function(){ $s=ct_store();$d=reinforcement_fixture(2);ct_cache($s,$d,3600);$r=MonContinuity::cachedSource($s,progress_test_config($s->dir),'HTTP_TRANSPORT_28',time());ct_ok($r['cached']&&$r['source_fetched_at']===mon_iso(time()-3600)&&MonRun::json($r['data'])===MonRun::json($d));});
ct_case('changed cached data cannot bypass hash verification',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));$d=$s->read('remote_cache.json');$d->collection->collection_id='tampered';$s->write('remote_cache.json',$d);ct_fault(static function()use($s){MonContinuity::cachedSource($s,progress_test_config($s->dir),'HTTP_TRANSPORT_28',time());},'MON_CONTINUITY_CACHE_HASH_INVALID');});
ct_case('authorization errors are not converted to offline success',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));ct_fault(static function()use($s){MonContinuity::cachedSource($s,progress_test_config($s->dir),'HTTP_403',time());},'HTTP_403');});
ct_case('cache expiration and repository scope mismatch are refused',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1),8*86400);ct_fault(static function()use($s){MonContinuity::cachedSource($s,progress_test_config($s->dir),'HTTP_TRANSPORT_28',time());},'MON_CONTINUITY_CACHE_UNAVAILABLE');ct_cache($s,reinforcement_fixture(1));$d=$s->read('remote_cache.json');$d->_mon_cache->branch='different';$s->write('remote_cache.json',$d);ct_fault(static function()use($s){MonContinuity::cachedSource($s,progress_test_config($s->dir),'HTTP_TRANSPORT_28',time());},'MON_CONTINUITY_CACHE_UNAVAILABLE');});
ct_case('one conflict retains successful peers and records repair plus analysis handoff',function(){$d=reinforcement_fixture(2);$ids=array_keys(get_object_vars($d->watchlist->detail_requests));$d->collection->detail_responses->{$ids[0]}=progress_response($d,$ids[0]);$bad=progress_response($d,$ids[1],'conflict','previous_verified');$bad->error='DETAIL_PRICE_BASIS_CONFLICT';$bad->conflict=true;$bad->usable=false;$d->collection->detail_responses->{$ids[1]}=$bad;$r=MonContinuity::build($d,null,time());ct_ok(count($r->rows)===2&&$r->rows[0]->usable_reported&&ct_has($r,'verify_alternative_source')&&ct_has($r,'prepare_select_save')&&!$r->overall_complete);});
ct_case('a new completed period creates a durable renewal task even for done requests',function(){$d=reinforcement_fixture(1);$sid=$d->watchlist->symbols[0]->symbol_id;$d->collection->detail_responses->$sid=progress_response($d,$sid);$session=$d->watchlist->calendar->markets[0]->sessions[1];$session->close_at=mon_iso(time()-10);$session->open_at=mon_iso(time()-3600);$r=MonContinuity::build($d,null,time());ct_ok(ct_has($r,'renew_period')&&$r->counts['current_missing']===1);});
ct_case('unpublished successful response remains visible and needs publication',function(){$d=reinforcement_fixture(1);$sid=$d->watchlist->symbols[0]->symbol_id;$pending=(object)['collection'=>(object)['_detail_only'=>true,'detail_responses'=>(object)[$sid=>progress_response($d,$sid)]]];$r=MonContinuity::build($d,$pending,time());ct_ok($r->rows[0]->usable_reported&&ct_has($r,'publish_collection')&&ct_has($r,'prepare_select_save'));});
ct_case('blocked/no-data and discovery shortfall are saved rather than dropped',function(){$d=reinforcement_fixture(1);$sid=$d->watchlist->symbols[0]->symbol_id;$b=progress_response($d,$sid,'blocked','no_data');$b->usable=false;$b->error='YAHOO_MAPPING_MISSING';$d->collection->detail_responses->$sid=$b;$d->analysis->discovery_state=(object)['countries'=>[(object)['country'=>'KR','shortfall'=>3,'completed_bar_date'=>$b->bars_as_of]]];$r=MonContinuity::build($d,null,time());ct_ok(ct_has($r,'repair_source')&&ct_has($r,'discovery_shortfall')&&count($r->rows)===1);});
ct_case('checkpoint is protected, idempotent across restart and preserves original analysis time',function(){$s=ct_store();$d=reinforcement_fixture(1);ct_cache($s,$d);$r=MonContinuity::checkpoint($s,time());$later=MonContinuity::checkpoint(new MonStore($s->dir),time()+1);ct_ok($r->revision===$later->revision&&$r->revision_created_at===$later->revision_created_at&&$later->analysis_as_of===$d->analysis->as_of&&strpos(file_get_contents($s->path('continuity.php')),MON_SETTINGS_PREFIX)===0);});
ct_case('resource pause saves only the existing checkpoint without claiming recovery',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));$r=MonContinuity::checkpoint($s,time());$v=MonContinuity::checkpoint($s,time()+5,null,true);ct_ok($v->revision===$r->revision&&$v->checked_at===$r->checked_at&&$v->resource_deferred===true);});
ct_case('all 30 requests survive report pagination and stale cursor is refused',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(30));$r=MonContinuity::checkpoint($s,time());$count=0;$cursor=0;do{$v=MonContinuity::view($s,$cursor,$r->revision);$count+=count($v['pending_jobs']);$cursor=$v['page']['next_cursor'];}while($cursor!==null);ct_ok($count===count($r->pending_jobs)&&count($r->rows)===30);ct_fault(static function()use($s){MonContinuity::view($s,8,str_repeat('a',64));},'MON_CONTINUITY_CURSOR_INVALID');});
ct_case('runtime result remote journal verifies a lost PUT response before writing again',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));$report=MonContinuity::checkpoint($s,time());$remote=null;$puts=0;$calls=0;$http=new MonHttp(null,static function($method,$url,$headers,$body)use(&$remote,&$puts,&$calls){$calls++;if($method==='PUT'){$puts++;$p=mon_decode($body);$remote=base64_decode($p->content,true);throw new MonFault('HTTP_TRANSPORT_28');}return ['status'=>$remote===null?404:200,'headers'=>[],'body'=>$remote??'{}'];});$cfg=progress_test_config($s->dir);$pub=new MonContinuityPublication($s,$http,$cfg);$n=time();$pub->step(microtime(true)+5,$n);$pub->step(microtime(true)+5,$n);$before=$calls;$pub->step(microtime(true)+5,$n+1);ct_ok($calls===$before,'retry spacing');$v=(new MonContinuityPublication($s,$http,$cfg))->step(microtime(true)+5,$n+31);ct_ok($puts===1&&$v['state']==='saved'&&$v['verified_revision']===$report->revision);$pub->step(microtime(true)+5,$n+32);ct_ok($calls===$before+1,'duplicate revision');});
ct_case('remote conflict preserves collection and backs off before rereading',function(){$s=ct_store();$d=reinforcement_fixture(1);ct_cache($s,$d);MonContinuity::checkpoint($s,time());$calls=0;$http=new MonHttp(null,static function($method)use(&$calls){$calls++;return ['status'=>$method==='PUT'?409:404,'headers'=>[],'body'=>'{}'];});$pub=new MonContinuityPublication($s,$http,progress_test_config($s->dir));$n=time();$pub->step(microtime(true)+5,$n);$v=$pub->step(microtime(true)+5,$n);ct_ok($v['error']==='GITHUB_CONFLICT');$pub->step(microtime(true)+5,$n+1);ct_ok($calls===2&&$s->read('remote_cache.json')->analysis->as_of===$d->analysis->as_of);});
ct_case('daemon source outage reaches local continuity checkpoint without replacing analysis',function(){$s=ct_store();$d=reinforcement_fixture(1);ct_cache($s,$d);$cfg=progress_test_config($s->dir);$daemon=new MonDaemon($s,$s->dir.'/fixture.env','synthetic');$r=new ReflectionClass($daemon);$method=$r->getMethod('readRemote');$method->setAccessible(true);$http=new MonHttp(null,static function(){throw new MonFault('HTTP_TRANSPORT_28');});$source=$method->invoke($daemon,new MonGitHub($http,$cfg),$cfg,microtime(true)+2);ct_ok($source['cached']&&$source['data']->analysis->as_of===$d->analysis->as_of);MonContinuity::checkpoint($s,time(),$source['source_error']);ct_ok(MonContinuity::view($s)['report_complete']);});
ct_case('native daemon tick continues quote collection after detail publication timeout',function(){
    $s=ct_store();$d=reinforcement_fixture(1);$sid=$d->watchlist->symbols[0]->symbol_id;ct_cache($s,$d);$cfg=progress_test_config($s->dir);
    $s->write('detail_pending.json',(object)['collection'=>(object)['_detail_only'=>true,'detail_responses'=>(object)[$sid=>progress_response($d,$sid)]]]);$puts=0;$quoteCalls=0;
    $http=new MonHttp(null,static function($method,$url)use($d,&$puts,&$quoteCalls){
        if(strpos($url,'api.github.com')!==false){if($method==='PUT'){$puts++;throw new MonFault('HTTP_TRANSPORT_28');}return ['status'=>200,'headers'=>[],'body'=>mon_json($d,false)];}
        if(strpos($url,'oauth2/tokenP')!==false)return ['status'=>200,'headers'=>[],'body'=>'{"access_token":"synthetic-token","expires_in":3600}'];
        if(strpos($url,'openapi.koreainvestment.com')!==false){$quoteCalls++;$at=(new DateTimeImmutable('@'.(time()-120)))->setTimezone(new DateTimeZone('Asia/Seoul'));return ['status'=>200,'headers'=>[],'body'=>mon_json((object)['rt_cd'=>'0','output2'=>[(object)['stck_bsop_date'=>$at->format('Ymd'),'stck_cntg_hour'=>$at->format('His'),'stck_prpr'=>'130','cntg_vol'=>'100']]])];}
        throw new MonFault('HTTP_503');
    });
    $daemon=new MonDaemon($s,$s->dir.'/fixture.env','synthetic');$rc=new ReflectionClass($daemon);
    foreach(['http'=>$http,'load'=>new MonDaemonLoad(static function(){return ['cores'=>2,'load1'=>0,'memory_total_bytes'=>1073741824,'memory_available_bytes'=>536870912,'cpu_busy_percent'=>10];})]as $name=>$value){$p=$rc->getProperty($name);$p->setAccessible(true);$p->setValue($daemon,$value);}
    $tick=$rc->getMethod('tick');$tick->setAccessible(true);$tick->invoke($daemon);
    $pending=$s->read('pending.json');ct_ok($puts===1&&$quoteCalls>0&&mon_get($pending,'dirty')===true&&count($pending->collection->quotes)===1,'quote checkpoint lost');
    $report=MonContinuity::checkpoint($s,time(),'HTTP_TRANSPORT_28');ct_ok(ct_has($report,'publish_quotes')&&ct_has($report,'publish_collection'));
});
ct_case('missing source still produces a saved explicit recovery result',function(){$s=ct_store();$r=MonContinuity::checkpoint($s,time());ct_ok($r->report_complete&&!$r->analysis_complete&&ct_has($r,'restore_verified_source'));});
ct_case('dirty quote checkpoint survives daemon restart as a publication job',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));$s->write('pending.json',(object)['dirty'=>true,'signature'=>'synthetic','collection'=>(object)['collection_id'=>'synthetic-pending']]);$a=MonContinuity::checkpoint($s,time());$b=MonContinuity::checkpoint(new MonStore($s->dir),time()+1);ct_ok(ct_has($b,'publish_quotes')&&$a->revision===$b->revision);});
ct_case('corrupt local report is rebuilt from verified source and does not break web status',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));file_put_contents($s->path('continuity.php'),'broken');ct_ok(MonContinuity::view($s)['state']==='journal_repair_required');$r=MonContinuity::checkpoint($s,time());ct_ok($r->report_complete&&MonContinuity::view($s)['revision']===$r->revision);});
ct_case('tampered pending remote bytes are discarded before any PUT',function(){$s=ct_store();ct_cache($s,reinforcement_fixture(1));MonContinuity::checkpoint($s,time());$calls=[];$http=new MonHttp(null,static function($method)use(&$calls){$calls[]=$method;return ['status'=>404,'headers'=>[],'body'=>'{}'];});$cfg=progress_test_config($s->dir);$p=new MonContinuityPublication($s,$http,$cfg);$p->step(microtime(true)+3,time());$j=$s->readPrivate('continuity-publication.php');$j->raw.='tampered';$s->writePrivate('continuity-publication.php',$j);$p->step(microtime(true)+3,time());ct_ok($calls===['GET','GET']);});
$failed=count(array_filter($cases,static function($c){return $c['result']==='FAIL';}));$out=['code'=>MON_VERSION,'php'=>PHP_VERSION,'memory_limit'=>ini_get('memory_limit'),'source_sha256'=>hash_file('sha256',dirname(__DIR__).'/mon.php'),'tests'=>count($cases),'passed'=>count($cases)-$failed,'failed'=>$failed,'seconds'=>mon_monotonic()-$started,'peak_memory_bytes'=>memory_get_peak_usage(true),'cases'=>$cases,'external_requests'=>0,'orders'=>0];file_put_contents(__DIR__.'/mon_continuity_tests.json',mon_json($out));echo mon_json($out);
foreach($dirs as $dir){foreach(glob($dir.'/*')as $f)@unlink($f);@rmdir($dir);}exit($failed?1:0);
